package com.ukulele.monitor;
import android.app.*;import android.os.Bundle;import android.widget.*;import android.view.*;import com.ukulele.monitor.ui.*;
public final class HelpActivity extends Activity {
 float uiScale=1f;
 protected void onCreate(Bundle b){super.onCreate(b);UiKit k=UiKit.create(this);
 // 跟随设置里的「界面字号」，避免帮助页与主界面字号不一致。
 try{uiScale=ScoreDocumentActivity.fontScale(SettingsStore.store(this).textScale());}catch(Exception ignored){uiScale=1f;}
 LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(k.dp(20),k.dp(20),k.dp(20),k.dp(24));body.setBackgroundColor(AppTheme.colors().bgRoot);body.addView(scaled(k.title("帮助与指南")));
 String[] titles={"导入与我的曲库","照片 / PDF离线识谱","音域与音调","全屏练习与倍速","回收站与恢复","灯光指引","连接与休眠","滑音和颤音","评分挑战","实时音频分析","四种音色与余音","效果组合与单音效果","模拟变调夹"};
 String[] texts={"通过导入选择MIDI、UKS1、事件文本、PDF或照片。原文件复制到应用内部，不依赖原文件位置；重复打开、重启和覆盖安装会保留。卸载或清除应用数据仍会删除曲库，重要原谱可通过管理菜单导出。", "清晰印刷四线TAB优先读取原指法及配套五线谱时值。单旋律简谱在手机本机识别主音、拍号、数字、八度点、附点、减时线、延音和基础同音连接。照片会先尝试自动找到纸面并做透视拉正；找不准时保留整图不裁正，可手动旋转，放大后“识别当前页”只读取可见区域。识别结果需对照原谱，特别是模糊、装饰音、反复和多结尾。简谱校对页上半看原图、下半改文稿：1—7是音级，0休止，-延一拍；1'高八度，5,低八度；1/2八分，1/4十六分；2.附点，1~ 1同音连接；|: 1 2 :|反复两次。?代表未确认区域，须补齐后才能生成指引。BPM按四分音符每分钟。A1:、A2:、B:定义段落，调整菜单可设置顺序、反复和整体八度；段落顺序与内部反复同时生效，避免重复展开。片段缺少反复结束时，可关闭反复先练已导入页面。手动升降号#、b在小节内生效；调式=自然小调可显式切换。保存草稿会保留文稿，生成指引前检查语法和音域。数字谱和纯TAB/独立五线谱的复杂布局仍须校对，不能把识别候选当完整正确演奏版本。校对后直接生成并练习，不必导出再导入MIDI；原文件与上一校对稿保留。完整源码依赖与许可在交付目录licenses，照片识别不上传到云端", "高G调弦为G4/C4/E4/A4，各弦0—18品，可用音域C4—D#6。超出音域会标记，不会自动折叠到另一个八度。吉他谱常含低音；在校对中明确改音名/移调后再确认。难度依据速度、密度、品位、跨度和同时音符数自动给出练习建议，不是考试等级。", "跟弹页和全屏下均可切换基准线：左侧基准时音符从右向左，右侧基准时从左向右；设置自动保存，切换不改变曲谱时间或评分。当前指法与时间刻度分行显示。全屏跟弹新增开始灯光指引、重新开始和弦序1→4/4→1按钮；未同步曲谱时会先同步并在设备确认后启动。重新开始会重置本轮进度，评分模式也会开始新一轮。弦序只改变显示排列，实际音高和灯阵接线不变。点击全屏跟弹获得横屏大音符，可暂停/继续、重头练习和选择0.25—2倍速。练习和设备灯光指引都支持0.25—2倍速，可在开始前选择或运行中调整；变速保留当前谱面进度，不改变音高和音色，不需要重新上传。设备指引可暂停/继续，暂停时灯阵保持当前提示。手机依据ESP32真实曲谱时钟回读更新；确认失败或超时会提示，旧ESP32只支持原速指引，需要升级才能启用设备倍速。倍速不会改写原曲谱，评分仍按速度分别保存最高成绩。", "移到回收站会隐藏曲谱，原件和练习数据仍保留，可随时恢复。默认不自动清空。选择30天或90天保留期后，过期项目自动永久删除；永久删除必须确认，不能恢复。", "选择曲目后同步到琴，再开始琴上的指引。新版音块与灯光共用精确开始/结束时间：休止熄灯，多音中结束的弦单独熄灭；重复同音保留短熄灯间隔。需要配套新版ESP32，升级后重新上传所选曲谱。新板支持同一拍最多四根弦的不同品位同时指引：空弦整列点亮，1—17品亮上下两灯，18品仅亮上灯。开启渐变后，每根弦按自身音长渐亮、渐灭，其他弦的长音可独立持续；短音保持清晰闪烁。休止熄灭，连续同音分别重触发。关闭渐变可恢复清晰断奏式指引。MIDI按音符实际起止生成，延音踏板不延长指引。灯阵页支持横/竖向以及全屏。开启评分后，本地跟弹通过实际拨弦音符反馈判定；评分可在跟弹页或全屏界面开启、关闭。", "在设置页连接你的琴。屏幕与手机均可唤醒；设备休眠/恢复期间控制暂不可用。断线或数据过期时界面显示待回读，不把缓存当实际状态。", "滑音和颤音各有开关，由设备回读确认。新版可选辅助电容揉弦或原品格判定。在「设置 → 演奏手势」可切换颤音判定，并保存颤音门限。门限范围为120–2400，默认360，两种判定共用。关闭滑音后不再接受新滑音。关闭颤音后清除已有判定，声音中的颤音沿包络淡出。设置保存到设备。", "在曲谱→练习开启评分，连接乐器并等待实时音符回读。点击开始评分练习，3秒准备后逐音演奏。仅按住品位不计分；使用FPGA送入音频引擎的拨弦音高回报，不使用手机麦克风。分数=100×正确音符数÷曲谱应弹音符数；错音与漏弹都保留，窗口内首次错音不能靠连续补弹改成正确，多弹也不会增加分数。比较音名及八度，相同音高可用其他弦演奏。判定宽容度按音符时长自动取（前后各120—300毫秒），相邻落点按中点分开。音块长度表示实际亮灯音长，竖线表示拨弦开始；评分宽容窗口单独计算，不改变音块和亮灯时间。由于拨弦反馈经蓝牙传回手机要晚20—150毫秒，判定窗口会整体前移抵消它；若仍常判你弹晚，可在「设置 → 评分宽容」往右调。本功能不是竞赛级音频测量。只有完整演奏才计最高成绩，按曲谱内容和速度分别保存；可以反复挑战。暂停保留本轮；换速度、换曲、断线、反馈缺失、进入后台或关闭评分会中止，不写最高成绩。全屏也能看到本轮与最高分。成绩保存在本机，卸载或清除数据会删除。", "演奏台提供频谱、波形和李萨如视图，可全屏查看。FFT在FPGA中对连续4096个最终音频样本计算；采样率48,828.125 Hz，频点间距11.92 Hz，采用Hann窗和固定dBFS刻度。横轴是频率Hz，纵轴是各频率分量相对数字满刻度的强弱。0 dBFS是上限，不是静音；−20 dBFS比−40 dBFS更强。幅度每减小10倍，约下降20 dB，所以−20、−40、−60 dBFS约对应满刻度的10%、1%、0.1%振幅。负号不代表负的能量，也不是环境声压dB SPL。峰的位置看频率，峰的高度看强弱；最高峰不一定是所弹音符的基频。频段/幅度按钮在频谱下切换0—2 kHz和完整频带，在波形/李萨如下切换1、2、4、8倍显示幅度。低于−72 dBFS的分析值按显示底限处理，不会把静音逐帧放大。波形接收256个未抽取16位样本，并从实际上升过零点对齐192点连续视窗，横轴约3.91 ms；1、2、4、8倍只影响显示。超量程的峰在边界截住，不改变真实音频。李萨如由FPGA生成，X为原始音频，Y为延迟32点、约0.655 ms的音频。DAC左右声道相同，因此这是延迟音频XY，不是两个独立立体声声道。图形按完整校验帧更新；显示刷新速度受SPI和蓝牙影响，不代表音频采样率；图内“数据帧/秒”表示完整数据更新速度。频谱完整校验后立即显示，不再增加跨帧平滑等待。波形与XY在新版固件下使用独立256点快速采集，避开4096点FFT等待；切回频谱仍计算完整4096点FFT。蓝牙频谱使用无损零段压缩，原始频点和PCM精度不变。旧固件自动回退完整快照。断线、休眠或数据超时会清除旧画面。需同时更新FPGA、ESP32和App，旧固件的低速抽样频谱不会当成新版完整频谱显示。", "前两种音色保留原有尤克里里与吉他参数。配套新版 FPGA 的拇指琴用快速衰减的高频模态还原簧片起音，光晕钟保留持续更久的钟体泛音。旧版 FPGA 仍显示其自身音色。切换选择只影响之后拨弦，已有声部自然衰减；动态声部用满时仍会按原分配策略接替旧声部。", "首页的效果组合可叠加电吉他失真、双声合唱、喷气弗兰格和节奏震音，顺序固定。勾选后调节各强度，点击应用组合，等待乐器确认。作用范围可选全部演奏音、某一根弦或下一次拨弦。下一音只选中一次实际拨弦事件，四弦同拍中也是一个事件；点击准备下一音可再次准备，其他音保持原声。已选中音符的效果尾音保留。单弦/单音处理弦振动发送，琴体公共共鸣保留原声。回到上方任一单效果选项可退出组合。", "设置页可将全部弦升高0至12个半音，相当于电子变调夹。应用后等待实际回读，恢复原调设为0。物理品位与灯光位置不变，发声音名、试听音高及评分同步转调。换变调夹会停止本轮评分与试听，请重新开始。"} ;
 for(int i=0;i<titles.length;i++){final String title=titles[i],text=texts[i];TextView v=scaled(k.textBold(title,16,AppTheme.colors().textPrimary));v.setPadding(0,k.dp(18),0,k.dp(18));v.setOnClickListener(w->showSection(title,text));body.addView(v);}ScrollView scroll=new ScrollView(this);scroll.addView(body);setContentView(scroll);}
 /** 按用户字号档位重设字号（UiKit 内部字号固定，只能在取回后缩放）。 */
 TextView scaled(TextView v){if(v!=null&&uiScale!=1f){float d=getResources().getDisplayMetrics().scaledDensity;if(d>0f)v.setTextSize(v.getTextSize()/d*uiScale);}return v;}
 /**
  * 帮助正文很长（最长一节约 700 字）。原来直接塞进 AlertDialog.setMessage：
  * 对话框正文区不滚动，超出屏幕的部分会被永久截断、用户根本看不到 —— 这正是「文字被遮挡」。
  * 改为把正文放进 ScrollView，长文可滚动读完，字号也跟随设置。
  */
 void showSection(String title,String text){
  UiKit k=UiKit.create(this);
  TextView content=scaled(k.text(text,14,AppTheme.colors().textSecondary));
  content.setLineSpacing(k.dp(4),1f);
  ScrollView scroller=new ScrollView(this);scroller.setPadding(k.dp(20),k.dp(8),k.dp(20),0);scroller.addView(content);
  com.ukulele.monitor.ui.AppDialogs.builder(this).setTitle(title).setView(scroller).setPositiveButton("知道了",null).show();
 }
}
